def threeSum(nums):
    s = sorted(nums); res = set()
    for i in range(len(s)):
        l, r = i + 1, len(s) - 1
        while l < r:
            t = s[i] + s[l] + s[r]
            if t == 0:
                res.add((s[i], s[l], s[r])); l += 1; r -= 1
            elif t < 0:
                l += 1
            else:
                r -= 1
    return [list(x) for x in sorted(res)]
